def predict(board_lines, action):
    grid = [list(row) for row in board_lines]
    rows, cols = 64, 64

    # Find player: connected B component at the bottom
    # The player is the B cells in rows 53-63
    player_cells = set()
    visited = set()
    queue = []

    # Start from all B cells in bottom rows
    for r in range(rows-1, rows-12, -1):
        for c in range(cols):
            if grid[r][c] == 'B' and (r, c) not in visited:
                queue.append((r, c))
                break
        if queue:
            break

    if not queue:
        return board_lines

    while queue:
        r, c = queue.pop(0)
        if (r, c) in visited:
            continue
        visited.add((r, c))
        player_cells.add((r, c))
        for nr, nc in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 'B' and (nr,nc) not in visited:
                queue.append((nr, nc))

    # Determine movement direction
    dr, dc = 0, 0
    if action == 'UP':
        dr = -1
    elif action == 'DOWN':
        dr = 1
    elif action == 'LEFT':
        dc = -1
    elif action == 'RIGHT':
        dc = 1
    else:
        return board_lines

    # Check if movement is blocked by walls
    for r, c in player_cells:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            if grid[nr][nc] == 'G' and (nr, nc) not in player_cells:
                return board_lines  # Blocked by wall

    # Collect blocks to push
    blocks_to_push = set()

    def collect_pushable(r, c):
        if (r, c) in blocks_to_push:
            return
        if grid[r][c] not in 'BGc':
            blocks_to_push.add((r, c))
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] not in 'G':
                    collect_pushable(nr, nc)

    for r, c in player_cells:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            if grid[nr][nc] not in 'BGc' and (nr, nc) not in player_cells:
                collect_pushable(nr, nc)

    # Check if blocks can be pushed
    for r, c in blocks_to_push:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            if grid[nr][nc] == 'G' and (nr, nc) not in blocks_to_push and (nr, nc) not in player_cells:
                return board_lines  # Can't push

    # Move everything
    new_grid = [row[:] for row in grid]

    # Clear old positions
    for r, c in player_cells:
        new_grid[r][c] = 'c'
    for r, c in blocks_to_push:
        new_grid[r][c] = 'c'

    # Move player
    for r, c in player_cells:
        nr, nc = r + dr, c + dc
        new_grid[nr][nc] = 'B'

    # Move blocks with color change
    color_map = {
        'b': 'O',
        'O': 'b',
        'N': 'R',
        'R': 'Y',
        'Y': 'G',
    }

    for r, c in blocks_to_push:
        nr, nc = r + dr, c + dc
        old_color = grid[r][c]
        new_color = color_map.get(old_color, old_color)
        new_grid[nr][nc] = new_color

    return [''.join(row) for row in new_grid]

